<script setup lang="ts">
import type { BsBillingCopy, BsManualPaymentView } from '../types/billingPresentation'
defineProps<{ copy: BsBillingCopy; view: BsManualPaymentView }>()
const reason = defineModel<string>('reason', { required: true })
defineEmits<{ close: []; refresh: []; select: [id: string]; file: [event: Event]; submit: []; cancel: []; download: [id: string]; openSubscription: [] }>()
</script>
<template>
  <BsDialog :visible="view.visible" :title="copy.notice" :dirty="view.dirty" :pending="view.pending" size="lg" @update:visible="value => { if (!value) $emit('close') }">
    <BsStack padding="lg"><BsText v-if="view.denied" role="alert">{{ copy.denied }}</BsText><template v-else><BsText v-if="view.pending" role="status">{{ copy.loading }}</BsText><BsText v-if="view.error" role="alert" tone="danger">{{ view.error }}</BsText><BsButton :disabled="view.pending || view.dirty" @click="$emit('refresh')">{{ copy.refresh }}</BsButton><BsText v-if="view.empty">{{ copy.empty }}</BsText><template v-if="view.selected"><BsText size="sm" tone="muted">{{ view.pendingHint }}</BsText><BsText emphasis="bold">{{ view.selected.title }}</BsText><BsText role="status">{{ view.selected.status }}</BsText><BsButton v-if="view.selected.approved" variant="primary" @click="$emit('openSubscription')">{{ copy.openSubscription }}</BsButton><BsText wrap="preserve">{{ view.selected.instructions }}</BsText><BsText>{{ copy.reference }}: {{ view.selected.reference }}</BsText><BsText v-if="view.selected.period">{{ view.selected.period }}</BsText><BsForm v-if="view.cancelAllowed" @submit.prevent="$emit('submit')"><BsFieldLabel v-if="view.uploadAllowed"><BsText>{{ copy.evidenceSelect }}</BsText><BsFileInput :key="view.fileKey" accept="image/jpeg,image/png,application/pdf" :disabled="view.pending" bare @change="$emit('file', $event)"/><BsText size="xs" tone="muted">{{ view.fileHint }}</BsText></BsFieldLabel><BsFloatingField :label="copy.reason"><BsTextarea v-model="reason" maxlength="1000" required :disabled="view.pending"/></BsFloatingField><BsInline><BsButton v-if="view.uploadAllowed" type="submit" :disabled="!view.canSubmit" :pending="view.pending" variant="primary">{{ copy.submit }}</BsButton><BsButton :disabled="view.pending || !reason.trim()" @click="$emit('cancel')">{{ copy.cancelRequest }}</BsButton></BsInline></BsForm><BsHeading :level="3">{{ copy.history }}</BsHeading><BsList :ordered="true" marker="none"><BsListItem v-for="event in view.history" :key="event.id">{{ event.text }}</BsListItem></BsList><BsList><BsListItem v-for="file in view.evidence" :key="file.id"><BsButton variant="link" :disabled="view.pending" @click="$emit('download', file.id)">{{ file.text }}</BsButton></BsListItem></BsList></template><BsList v-if="view.requests.length > 1"><BsListItem v-for="request in view.requests" :key="request.id"><BsButton variant="link" :disabled="view.pending || view.dirty" @click="$emit('select', request.id)">{{ request.text }}</BsButton></BsListItem></BsList></template></BsStack>
  </BsDialog>
</template>
